```tsx
export default function App() {
  // A component is just a capitalized function that returns JSX.
  // It can be reused as many times as you want.
  return (
    <main>
      <Greeting name="Ada" />
      <Greeting name="Linus" />
    </main>
  );
}

function Greeting({ name }: { name: string }) {
  return <p>Hello, {name}!</p>;
}
